private static int decodeOctets(int i,ByteBuffer bb,StringBuilder sb){
    int b0 = bb.get(i) & 0xFF;
    if (b0 <= 0x7F) {
        sb.append((char) b0);
        return i + 1;
    }
    // Determine sequence length
    int seqLen;
    int mask;
    if ((b0 >> 5) == 0x6) { // 110xxxxx
        seqLen = 2;
        mask = 0x1F;
    } else if ((b0 >> 4) == 0xE) { // 1110xxxx
        seqLen = 3;
        mask = 0x0F;
    } else if ((b0 >> 3) == 0x1E) { // 11110xxx
        seqLen = 4;
        mask = 0x07;
    } else {
        sb.append('?');
        return i + 1;
    }
    // Check if enough bytes available
    if (i + seqLen > bb.limit()) {
        sb.append('?');
        return i + 1;
    }
    int codepoint = (b0 & mask) << ((seqLen - 1) * 6);
    for (int j = 1; j < seqLen; j++) {
        int b = bb.get(i + j) & 0x3F;
        codepoint |= b << ((seqLen - 1 - j) * 6);
    }
    if (seqLen == 4) {
        // surrogate pair
        int cp = codepoint;
        cp -= 0x10000;
        sb.append((char) ((cp >> 10) + 0xD800));
        sb.append((char) ((cp & 0x3FF) + 0xDC00));
    } else {
        sb.append((char) codepoint);
    }
    return i + seqLen;
}

