public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Clear any existing data in the buffer
    buffer.clear();
    // Serialize the message into the buffer using the provided schema
    schema.writeTo(buffer, message);
    // Retrieve the serialized byte array from the buffer
    byte[] data = buffer.toByteArray();
    int size = data.length;
    // Write the length prefix in varint format
    int tmp = size;
    while ((tmp & 0xFFFFFF80) != 0) {
        out.write((tmp & 0x7F) | 0x80);
        tmp >>>= 7;
    }
    out.write(tmp);
    // Write the serialized message to the OutputStream
    out.write(data);
    // Reset the buffer for next use
    buffer.clear();
    return size;
}

