}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || len <= 0) {
        return 0;
    }
    int count = 0;
    int start = index;
    int end = Math.min(index + len, str.length());
    int i = start;
    while (i < end) {
        int cp = str.codePointAt(i);
        int bytes;
        if (cp <= 0x7F) {
            bytes = 1;
        } else if (cp <= 0x7FF) {
            bytes = 2;
        } else if (cp <= 0xFFFF) {
            bytes = 3;
        } else {
            bytes = 4;
        }
        count += bytes;
        i += Character.charCount(cp);
    }
    return count;
}

