public long readRawVarint64() throws IOException {
    long result = 0L;
    int shift = 0;
    while (true) {
        int b = this.read();
        if (b == -1) {
            throw new EOFException();
        }
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
        if (shift >= 64) {
            throw new IOException("Malformed Varint");
        }
    }
}

private void pop(final String descriptor){
    int p = descriptor.indexOf('(');
    if (p >= 0) { // method descriptor
        int end = descriptor.indexOf(')', p);
        if (end < 0) {
            return; // malformed descriptor
        }
        String types = descriptor.substring(p + 1, end);
        int i = 0;
        while (i < types.length()) {
            char c = types.charAt(i);
            if (c == 'L') { // reference type
                int semicolon = types.indexOf(';', i);
                if (semicolon < 0) {
                    return; // malformed
                }
                i = semicolon + 1;
                --pos;
            } else if (c == '[') { // array type
                i++;
                while (i < types.length() && types.charAt(i) == '[') {
                    i++;
                }
