                    if (types.charAt(i) == 'L') {
                        int semicolon = types.indexOf(';', i);
                        if (semicolon < 0) {
                            return; // malformed
                        }
                        i = semicolon + 1;
                    } else {
                        i++;
                    }
                }
                --pos;
            } else { // primitive
                i++;
                --pos;
            }
        }
    } else { // single type descriptor
        int i = 0;
        while (i < descriptor.length()) {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon < 0) {
                    return; // malformed
                }
                i = semicolon + 1;
                --pos;
            } else if (c == '[') {
                i++;
