final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // retrieve the location of the UTF-8 pool entry within the class file buffer
    // (assumes an int[] constantPoolOffsets holds the start offsets of each entry)
    int offset = constantPoolOffsets[constantPoolEntryIndex];
    // the length of the modified UTF‑8 string is stored in the first two bytes of the entry
    int utfLen = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    int byteStart = offset + 2;
    // decode the bytes of the UTF‑8 entry
    String result = new String(classFileBuffer, byteStart, utfLen, java.nio.charset.StandardCharsets.UTF_8);
    // copy the decoded characters into the supplied buffer
    result.getChars(0, result.length(), charBuffer, 0);
    return result;
}

