private void pop(final String descriptor) {
    int slots = 0;
    int idx = 0;
    // method descriptor
    if (descriptor.charAt(0) == '(') {
        idx = 1;
        while (idx < descriptor.length() && descriptor.charAt(idx) != ')') {
            char c = descriptor.charAt(idx);
            // skip array brackets
            while (c == '[') {
                idx++;
                c = descriptor.charAt(idx);
            }
            if (c == 'L') {
                // reference type
                slots++;
                idx++; // skip 'L'
                while (idx < descriptor.length() && descriptor.charAt(idx) != ';') {
                    idx++;
                }
                idx++; // skip ';'
            } else {
                // primitive type
                if (c == 'J' || c == 'D') {
                    slots += 2;
                } else {
                    slots += 1;
                }
                idx++;
            }
        }
    } else {
        // single type descriptor
        char c = descriptor.charAt(0);
        if (c == '[') {
            // array type – always 1 slot
            slots = 1;
        } else if (c == 'L') {
            slots = 1;
        } else {
            slots = (c == 'J' || c == 'D') ? 2 : 1;
        }
    }
    // pop the calculated number of slots from the stack
    for (int i = 0; i < slots; i++) {
