public static String applyRelativePath(String path,String relativePath){
    String[] baseParts = path.split("/");
    String[] relParts = relativePath.split("/");
    ArrayDeque<String> stack = new ArrayDeque<>();
    // Preserve leading slash if present
    if (path.startsWith("/")) {
        stack.addLast("");
    }
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("")) {
                stack.removeLast();
            }
            continue;
        }
        stack.addLast(part);
    }
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("")) {
                stack.removeLast();
            }
            continue;
        }
        stack.addLast(part);
    }
    StringBuilder sb = new StringBuilder();
    if (stack.isEmpty()) {
        sb.append(".");
    } else {
        Iterator<String> it = stack.iterator();
        while (it.hasNext()) {
            String seg = it.next();
            if (seg.isEmpty()) {
                sb.append("/");
            } else {
                if (sb.length() > 0 && sb.charAt(sb.length() - 1) != '/') {
                    sb.append("/");
                }
                sb.append(seg);
            }
        }
    }
    return sb.toString();
}

